"""Build source-grounded L241-L245 ingestion governance notes."""
from __future__ import annotations
import argparse,json
import promote_l231_l235_notes as base
from format_knowledge_notes import normalize_markdown
from promote_l201_l205_notes import Lesson

ROOT,PACK,WIKI,MODULE=base.ROOT,base.PACK,base.WIKI,base.MODULE
FD='src.book.reis-housley-fundamentals-data-engineering'; DD='src.book.kleppmann-ddia.1e'; AS='src.web.airbyte-schema-change-management'; CS='src.web.confluent-schema-evolution'; DM='src.web.aws-dms-data-validation'; GS='src.web.google-sre-capacity-load-testing'; MR='src.web.madr-templates'; AI='src.web.airbyte-incremental-append-deduped'
FDL='SRC-REIS-HOUSLEY-FUNDAMENTALS-DATA-ENGINEERING'; DDL='SRC-KLEPPMANN-DDIA-1E'; ASL='SRC-AIRBYTE-SCHEMA-CHANGE-MANAGEMENT'; CSL='SRC-CONFLUENT-SCHEMA-EVOLUTION'; DML='SRC-AWS-DMS-DATA-VALIDATION'; GSL='SRC-GOOGLE-SRE-CAPACITY-LOAD-TESTING'; MRL='SRC-MADR-TEMPLATES'; AIL='SRC-AIRBYTE-INCREMENTAL-APPEND-DEDUPED'

LESSONS=(
Lesson(241,'Lesson_241-schema-drift-detect-classify-quarantine','Schema Drift Detection Classification and Quarantine','129-schema-drift-detection-classification-quarantine.md','wiki.ingestion.schema-drift-detection-classification-quarantine','Schema drift được phát hiện, phân loại và cô lập thế nào để tránh vừa mất dữ liệu vừa phát tán sai nghĩa?',(AS,CS,FD),(ASL,CSL,FDL),(
('Ba lớp thay đổi','Tách physical schema, logical contract và semantic meaning. Thêm cột nullable có thể compatible ở storage nhưng làm downstream `select *` đổi shape; đổi enum meaning không đổi type nhưng là semantic break. Snapshot schema phải gồm field path, type, nullable, default, key/cursor role, constraints và version. Diff tên cột đơn thuần không đủ.'),
('Phân loại theo tác động','Nhóm additive, restrictive, destructive, identity/order breaking và semantic-only. Với từng change, đánh giá reader/writer compatibility, lịch sử, backfill, downstream dependency và privacy. Xóa cursor/primary key là critical vì phá incremental identity; widening type có thể an toàn ở source nhưng không ở target. Classification dẫn tới action, không chỉ severity label.'),
('Detect và version','Discover trước sync theo cadence có SLO, lưu canonical schema hash và diff với approved version. Event schema cũng cần registry compatibility và subject/version policy. Detection lag là một metric vì change có thể đi qua trước lần discover. Manual refresh, connector upgrade và config change đều có thể tạo diff, nên provenance của change phải được lưu.'),
('Quarantine envelope','Quarantine giữ raw payload, source boundary, schema observed/expected, reason code, connector version, first/last seen, count/bytes và retry lineage trong vùng truy cập hẹp. Không drop record lặng lẽ, cũng không cho unknown field/type đi thẳng vào curated table. Quarantine là state có owner, TTL, disposition và replay path; không phải thư mục rác vô hạn.'),
('Decision table','Compatible additive có thể land raw và mở field sau approval; coercible change cần explicit transform và loss test; incompatible type/key/cursor dừng affected stream; semantic-only cần owner xác nhận và downstream versioning. Backfill quyết định riêng với propagation. Same field name đổi unit/currency/timezone là breaking dù parser vẫn xanh.'),
('Failure lab','Inject add/drop/rename/type narrowing, key removal, nested-path change, enum meaning change và connector major upgrade. Assert exact classification, pause/continue policy, zero silent loss, quarantine evidence và deterministic replay after approval. So raw count/hash trước–sau; chứng minh old readers behavior. Lưu schema snapshots, diff, decision và downstream test results.'),
),tuple(f'Schema-drift probe {i}: observed diff, compatibility class, action, quarantine evidence và replay oracle phải đủ' for i in range(1,16))),
Lesson(242,'Lesson_242-reconciliation-from-source-to-landing','Source to Landing Reconciliation','130-source-to-landing-reconciliation.md','wiki.ingestion.source-to-landing-reconciliation','Đối soát source–landing ở những tầng nào để phát hiện missing, duplicate, corruption và semantic coercion?',(DM,FD,DD),(DML,FDL,DDL),(
('Boundary trước số liệu','Mọi phép đối soát cần cùng source boundary: snapshot ID, LSN/SCN, watermark tuple, API cursor window hoặc file manifest. So source đang chuyển động với landing của thời điểm khác tạo false mismatch. Ghi included/excluded scope, timezone, delete state, late-data allowance và validation delay. Không có boundary thì “khớp” không có nghĩa xác định.'),
('Bốn tầng oracle','Tầng 1 control count theo entity/partition. Tầng 2 key-set và duplicate/missing direction. Tầng 3 typed canonical row/column hash sau khi chuẩn hóa có công bố. Tầng 4 business aggregates/invariants theo grain. Count có thể khớp khi một missing bù một duplicate; hash có thể lệch do canonicalization chứ không do data loss. Dùng nhiều tầng và drill-down diff.'),
('Canonicalization','Định nghĩa null/empty, Unicode normalization, timezone, decimal scale/rounding, NaN, binary, array/map order và collation trước hash. Hash field có length-prefix hoặc structured serialization để tránh ambiguity. Không ép mọi source về string không type. Lưu algorithm/version và field inclusion; masking hoặc unsupported columns phải được báo là coverage gap.'),
('Mismatch taxonomy','Phân biệt missing target, extra target, value diff, unvalidated/suspended, schema mismatch, late but expected và source-mutated-during-validation. Mỗi class có owner, severity, retry/revalidate, containment và escalation. Validation tool xanh chỉ trong supported scope; primary key absence hoặc concurrent mutation có thể làm coverage giảm mà không phải pipeline correctness.'),
('Chi phí và lấy mẫu','Full row compare tốn query, network và compute; partition/range/hash tree có thể khoanh vùng. Sampling chỉ ước lượng và có risk model, không chứng minh zero loss. Validation concurrency có budget riêng để không gây sự cố nguồn. SLO gồm coverage, residual mismatch age và time-to-explain, không chỉ pass rate.'),
('Reconciliation lab','Tạo fixed-boundary source và landing, inject one missing, one duplicate, swapped values, timezone coercion, hard delete và concurrent update. Chứng minh count-only bỏ sót ca bù trừ; key set tìm direction; typed hash tìm field diff; aggregate phát semantic error. Lưu queries, inputs, raw diffs, unresolved exclusions và signed disposition.'),
),tuple(f'Reconciliation probe {i}: common boundary, control level, canonicalization, mismatch class và raw diff phải nối được' for i in range(1,16))),
Lesson(243,'Lesson_243-ingestion-slo-and-the-backfill-isolation-rule','Ingestion SLO and Backfill Isolation Rule','131-ingestion-slo-backfill-isolation.md','wiki.ingestion.ingestion-slo-backfill-isolation','Định nghĩa ingestion SLO và cô lập backfill thế nào để phục hồi lịch sử không phá dữ liệu mới?',(GS,FD,AS),(GSL,FDL,ASL),(
('SLI từ consumer deadline','Freshness đo event/source-boundary tới publish-ready, không lấy job success làm proxy. Completeness đo accepted expected units tại boundary; correctness dựa reconciliation residual; availability đo khả năng đọc published data. Chọn percentile/window, population và exclusions. Mỗi SLI có exact query, clocks, owner và data-delay semantics.'),
('SLO và error budget','SLO là target theo rolling window cùng burn alerts; không phải 100% slogan. Tách daily path và historical backfill populations. Error budget giúp quyết định freeze change, giảm concurrency hoặc ưu tiên remediation. Một run xanh nhưng checkpoint lag tăng vẫn có thể vi phạm freshness. Dashboard phải hiển thị denominator và missing telemetry.'),
('Backfill là workload khác','Backfill đọc volume lớn, dùng historical schema, có late/delete/restate semantics và tạo write amplification. Nó cần queue, worker pool, source quota, storage namespace, target compute và checkpoint riêng. Daily path giữ reserved capacity và priority. Không dùng cùng watermark state hoặc overwrite current publication bằng partial historical range.'),
('Admission và isolation','Áp max in-flight, rate/compute budget, partition lease, pause threshold và maintenance window theo source/target. Capacity test xác định safe envelope; production backfill bắt đầu nhỏ và ramp theo lag/error signals. Khi daily freshness burn tăng, backfill tự giảm hoặc dừng. Isolation được chứng minh bằng noisy-neighbor experiment, không bằng tên queue.'),
('Publication và reconciliation','Backfill ghi versioned partitions/table branch, reconcile theo range rồi atomic publish/swap. Nếu sửa lịch sử, policy nêu affected metrics, notification, restatement version và rollback. Idempotent range identity ngăn double apply. Daily and backfill overlap cần precedence hoặc same canonical merge rule; nếu không, kết quả phụ thuộc race.'),
('SLO experiment','Chạy daily stream ở steady load; thêm backfill 1x, 2x, 4x trong sandbox. Đo p50/p95 freshness, source latency, throttling, target queue, checkpoint lag và reconciliation. Chứng minh daily SLO giữ trong envelope; inject backfill failure/restart và overlapping range. Ghi reversal threshold, chưa biến test thành universal capacity claim.'),
),tuple(f'Ingestion-SLO probe {i}: SLI population, deadline, backfill resource, isolation signal và stop rule phải cụ thể' for i in range(1,16))),
Lesson(244,'Lesson_244-connector-landscape-build-adopt-or-buy','Connector Landscape Build Adopt or Buy','132-connector-landscape-build-adopt-buy.md','wiki.ingestion.connector-landscape-build-adopt-buy','Quyết định tự xây, dùng open-source hay mua connector dựa trên semantics, vận hành và exit cost nào?',(FD,AS,MR),(FDL,ASL,MRL),(
('Bắt đầu từ contract','Lập source profile: auth, entities, key/cursor/delete, snapshot/CDC/pagination/file semantics, schema drift, rate limits, volume, latency, replay và compliance. Connector coverage được chấm từng capability với evidence. Danh sách logo hay “supported source” không chứng minh hard delete, historical backfill hoặc exact field coverage.'),
('Ba lựa chọn','Build cho control/special semantics nhưng gánh maintenance; adopt open-source tăng visibility/extensibility nhưng vẫn sở hữu deploy/upgrade/on-call; buy chuyển một phần vận hành/SLA cho vendor nhưng thêm pricing, lock-in, telemetry và roadmap dependency. Hybrid/fork cũng là lựa chọn có merge debt. So total obligation, không so license fee duy nhất.'),
('Scorecard có hard gates','Hard gates: security/compliance, required change semantics, recovery/replay, region/network và data ownership. Weighted criteria: coverage, reliability evidence, operability, extensibility, latency, cost, support, upgrade behavior và exit. Hard gate fail không được điểm đẹp bù. Trọng số và uncertainty do owner ký; sensitivity analysis chỉ ra khi ranking đảo.'),
('Proof of concept','PoC phải dùng representative source và failure suite: initial load, incremental update/delete, schema drift, rate limit, expired cursor/token, crash/restart, duplicate delivery và backfill. Thu raw logs, checkpoint, lineage, reconciliation, resource/cost. Happy-path row movement không phải PoC. Pin connector/platform versions và config.'),
('Vòng đời và exit','Đánh giá upgrade cadence, major migration, CVE, support escalation, state format, normalization behavior và ownership khi connector deprecated. Exit plan cần export checkpoint/state, raw retention, canonical schema, cutover dual-run và reconciliation. Vendor SLA không thay source owner relationship hay internal incident response.'),
('ADR quyết định','ADR ghi context, options, evidence, decision, rejected reasons, assumptions, consequences, cost model và reversal triggers. Cost gồm engineering/on-call, source impact, destination compute, egress, re-sync và incident. Review sau 30/90 ngày bằng observed metrics. Không gọi quyết định “chuẩn” ngoài exact source và constraints.'),
),tuple(f'Connector-decision probe {i}: required semantics, hard gate, PoC evidence, lifecycle cost và reversal trigger phải rõ' for i in range(1,16))),
Lesson(245,'Lesson_245-ingestion-capstone-three-sources-into-one-raw-zone','Three Source Ingestion Capstone','133-three-source-ingestion-capstone.md','wiki.ingestion.three-source-ingestion-capstone','Capstone ba nguồn phải tạo chuỗi bằng chứng nào để chứng minh raw zone complete, replayable và vận hành được?',(FD,DM,AS,AI),(FDL,DML,ASL,AIL),(
('Ba nguồn có semantics khác','Case gồm API có cursor/rate limit, database snapshot plus changes và file drop có manifest. Mỗi nguồn có extraction contract riêng; không ép chung một watermark. Raw zone dùng shared envelope nhưng giữ source-native boundary, identity, schema/version và payload fidelity. Capstone chấm tính đúng của từng path và khả năng quan sát chung.'),
('Hồ sơ kiến trúc','Nộp source contracts, decision ADR, sequence/failure diagrams, schema registry/diffs, landing envelope, checkpoint ledger, manifest/object map, access/retention policy và runbook. Mỗi artifact có locator/version/owner. Diagram không thay executable evidence. Secret chỉ là reference; test data synthetic hoặc đã được phê duyệt.'),
('Pipeline invariant','Thứ tự acquire, land immutable, validate/reconcile, publish và checkpoint. API page, DB chunk/log interval và file batch đều có deterministic ingestion identity. Retry có thể replay nhưng không tạo silent gap; same identity different content bị quarantine. Publication chỉ mở dữ liệu đã đủ manifest/schema/integrity checks.'),
('Failure campaign','Inject 429, lost response, cursor expiry, snapshot chunk retry, replica lag, schema breaking change, incomplete file batch, checksum mismatch, duplicate delivery và crash ở mỗi checkpoint boundary. Expected state/action viết trước. Một job tự recover nhưng làm mất key vẫn fail. Lưu timeline, state transitions, raw hashes, metrics và reconciliation diffs.'),
('SLO và vận hành','Định nghĩa per-source freshness/completeness/correctness cùng common incident severity. Backfill có quota riêng. Dashboard thể hiện boundary lag, pending/quarantine, retry amplification, source impact và validation residual. Runbook có triage, containment, replay, revalidation, rollback và communication. Game day có observer và stop rules.'),
('Điều kiện bảo vệ','Đạt khi ba source boundaries truy được tới published objects; rerun cùng input cho cùng accepted state; injected loss/collision bị phát hiện; daily path giữ SLO trong test envelope; reviewer độc lập tái hiện một failure. Chưa chạy production load, security review hay legal approval thì không gọi production-ready.'),
),tuple(f'Capstone probe {i}: source boundary, invariant, injected failure, evidence locator và independent oracle phải đủ' for i in range(1,16))),
)

QUERIES={241:['Schema drift phân loại thế nào?','Khi nào phải quarantine?','Xóa cursor có tác động gì?'],242:['Bốn tầng reconciliation là gì?','Canonical row hash thiết kế thế nào?','Count khớp có đủ không?'],243:['Backfill isolation gồm gì?','Ingestion SLI đo thế nào?','Khi nào phải dừng backfill?'],244:['Build adopt buy connector quyết định ra sao?','Connector PoC cần failure nào?','Exit plan gồm gì?'],245:['Capstone ba nguồn cần artifact gì?','Failure campaign gồm gì?','Điều kiện bảo vệ raw zone là gì?']}
NEW=((AS,'1_Nguon/Web/SRC-AIRBYTE-SCHEMA-CHANGE-MANAGEMENT.md','https://docs.airbyte.com/platform/using-airbyte/schema-change-management','public-vendor-documentation'),(DM,'1_Nguon/Web/SRC-AWS-DMS-DATA-VALIDATION.md','https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Validating.html','public-vendor-documentation'))
folder=base.folder;deep=base.deep;curriculum=base.curriculum
def manifest(check=False):
 p=ROOT/'Docs/Second-Brain/second-brain-manifest.json';d=json.loads(p.read_text());ids={x[0] for x in NEW};d['source_registry']=[r for r in d['source_registry'] if r.get('source_id') not in ids]+[{'source_id':i,'record_path':q,'canonical_url':u,'captured':'2026-10-02','rights':r} for i,q,u,r in NEW];nids={x.note_id for x in LESSONS};d['note_registry']=[n for n in d['note_registry'] if n.get('note_id') not in nids];d['retrieval_test_set']=[q for q in d['retrieval_test_set'] if q.get('expected_note_id') not in nids]
 for x in LESSONS:d['note_registry'].append({'note_id':x.note_id,'path':f'2_Wiki/Database-Systems/{x.title}.md','status':'review','source_ids':list(x.sources),'last_verified':'2026-10-02'});d['retrieval_test_set'].extend({'query':q,'expected_note_id':x.note_id} for q in QUERIES[x.number])
 d.update({'version':'1.0.48','updated_at':'2026-10-02T23:59:10+07:00'});d['layers']['1_Nguon']['source_count']=len(d['source_registry']);d['layers']['2_Wiki']['note_count']=len(d['note_registry']);e=json.dumps(d,ensure_ascii=False,indent=2)+'\n'
 if check:return [] if p.read_text()==e else [str(p.relative_to(ROOT))]
 p.write_text(e);return []
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--check',action='store_true');a=ap.parse_args();st=[]
 for x in LESSONS:
  k=normalize_markdown(deep(x));n,z=curriculum(x,k)
  for p,c in ((PACK/x.filename,k),(WIKI/f'{x.title}.md',k),(folder(x)/'note.md',n),(folder(x)/'after-note.md',z)):
   if a.check:
    if not p.exists() or p.read_text()!=c:st.append(str(p.relative_to(ROOT)))
   else:p.write_text(c)
 st+=manifest(a.check)
 if st:print('STALE\n'+'\n'.join(st));return 1
 print(('checked' if a.check else 'written')+f'={len(LESSONS)*4} stale=0');return 0
if __name__=='__main__':raise SystemExit(main())
